function gLocalHtml(from,to,pw,q){const L=gLinesAll(from,to);if(!L.length)return "";const sum=a=>a.reduce((t,x)=>t+(Number(x.total)||0),0);
  const loc=L.filter(x=>x.kind==="local"),spec=L.filter(x=>x.kind==="specialty"),ret=L.filter(x=>x.kind==="retail");const all$=sum(L),loc$=sum(loc);
  const wm=loc.map(x=>({x,m:gLineMiles(x)})).filter(o=>o.m!=null);const wm$=sum(wm.map(o=>o.x));
  const avg=wm$?Math.round(wm.reduce((t,o)=>t+o.m*(Number(o.x.total)||0),0)/wm$):null;const within=n=>sum(wm.filter(o=>o.m<=n).map(o=>o.x));
  const son=loc.reduce((t,x)=>t+gLineCounties(x).filter(([c])=>c==="Sonoma").reduce((a,[,k])=>a+k*(Number(x.total)||0),0),0);
  const byC=new Map();for(const x of loc)for(const [c0,k] of gLineCounties(x)){const c=c0||"Not known yet";const e=byC.get(c)||{c,total:0,prods:new Set()};e.total+=k*(Number(x.total)||0);e.prods.add(gKey(x.producer));byC.set(c,e)}
  const counties=[...byC.values()].sort((a,b)=>b.total-a.total);
  const nProd=new Set(loc.map(x=>gKey(x.producer))).size;
  let h=`${gCardO("miles","How far our food travels",avg!=null?avg+" miles on average, "+gPct(son,loc$)+" from Sonoma County":"Not known yet")}
    <div class="gstats">${[[avg!=null?avg+" miles":"Not known yet","average distance, by what was spent"],[gPct(son,loc$),"from Sonoma County"],[gPct(within(50),wm$),"grown within 50 miles"],ret.length?[gPct(loc$,all$),"of food spending to California farms and food hubs"]:[String(nProd),"California farms, producers and food hubs"]].map(([v,l])=>`<div class="gstat"><b>${esc(v)}</b><span>${esc(l)}</span></div>`).join("")}</div>
    <div class="lbl" style="margin-top:10px">By county</div><div class="tlist">${counties.map(e=>`<div class="prow"><div><b>${esc(e.c==="Not known yet"?e.c:e.c+(e.c.length>2?" County":""))}</b><div class="cnt">${e.prods.size} producer${e.prods.size===1?"":"s"}</div></div><div class="cnt" style="flex:none">${gMoney(e.total)} · ${gPct(e.total,loc$)}</div></div>`).join("")}</div>
    <div class="hint">Straight line miles from each farm's town to the school. A FEED bin counts the farms FEED listed for it that week. A farm with no town yet is left out of the miles until one is added under Producers, and so are bins from before TREE kept FEED's weekly farm lists.</div></div></details>`;
  // where the money went
  h+=`${gCardO("dollars","Where the food dollars went",gMoney(loc$)+" to California farms and food hubs")}
    <div class="gstats">${[[gMoney(loc$),"to "+nProd+" California farms, producers and food hubs"],[gMoney(son),"to Sonoma County farms and businesses"],[gMoney(sum(spec)),"to specialty suppliers chosen for quality"],[gMoney(sum(ret)),"to large retailers"]].map(([v,l])=>`<div class="gstat"><b>${esc(v)}</b><span>${esc(l)}</span></div>`).join("")}</div>
    ${ret.length?gRetailTrend(from,to):`<div class="cnt" style="margin-top:8px">No purchases from large retailers are kept ${pw}. Add Trader Joe's, Costco or others by hand below, or forward their receipts to the TREE mailbox, to see their share fall over time.</div>`}
    <div class="cnt" style="margin-top:10px">Across California, preschools in the Farm to School program bought 60 percent of their food directly from producers and 27 percent through food hubs, with under 1 percent from grocery supercenters. The same independent evaluation found each dollar of state grants to farmers generated about $2.10 in economic activity across the state. That figure is for grants to farms statewide, so it is context for this school's spending, never a measure of it.</div>
    <div class="cnt">Sources, <a href="https://californiafarmtoschooleval.org/wp-content/uploads/2026-f2s-prgrpt_ece-case-study.pdf" target="_blank" rel="noopener">California Farm to School Evaluation, early care and education case study, 2026</a> and <a href="https://californiafarmtoschooleval.org/wp-content/uploads/2026-f2s-prgrpt_est-econ-impacts.pdf" target="_blank" rel="noopener">economic impacts brief, 2026</a>.</div></div></details>`;
  // specialty suppliers, outside the grant
  if(spec.length){const byP=new Map();for(const x of spec){const k=gKey(x.producer);const e=byP.get(k)||{p:gProducer(x.producer),total:0,items:new Set(),n:0};e.total+=Number(x.total)||0;e.items.add(x.item);e.n++;byP.set(k,e)}
    h+=`${gCardO("specialty","Chosen for quality, not California grown",gMoney(sum(spec)))}
      <div class="cnt" style="margin-bottom:8px">Kept here so the full picture of the food is in one place. These are left out of the grant's California food totals.</div>
      <div class="tlist">${[...byP.values()].map(e=>`<div class="prow"><div style="min-width:0"><b>${esc(e.p.name)}</b>${e.p.town?` <span class="cnt">${esc(e.p.town)}</span>`:""}<div class="cnt">${gMoney(e.total)} · ${e.n} line${e.n===1?"":"s"} · ${esc([...e.items].join(", "))}</div>${gEvidence(e.p)}</div></div>`).join("")}</div></div></details>`}
  return h}
// what families do not have to provide, an estimate from the school days and meals on the menus and the children
