function gSavingsHtml(from,to,q){const S=gSet();const kids=Number(S.enrolled)||kidsAt().length||0;const {full,short,days}=gSchoolDays(from,to);
  if(!days)return `${gCardO("savings","What families don't have to provide","No school days yet")}<div class="empty">No monthly menus are kept for ${esc(periodName(q))}, so there are no school days to count yet.</div></div></details>`;
  const lo=full*G_SAVE.low+short*G_SAVE.lowShort,hi=full*G_SAVE.high+short*G_SAVE.highShort,fed=full*G_SAVE.fed+short*G_SAVE.fedShort;
  const hLo=days*G_SAVE.minLow/60,hHi=days*G_SAVE.minHigh/60;const meals=kids*(full*3+short*2);const r=n=>"$"+Math.round(n).toLocaleString("en-US");const hr=n=>Math.round(n).toLocaleString("en-US");
  const w=gWeek();
  return `${gCardO("savings","What families don't have to provide",hr(days)+" school days with lunch and snacks")}
    <div class="lbl">In a typical school week, for each family</div>
    <div class="gstats">${[["$"+Math.round(w.lo)+" to $"+Math.round(w.hi),"in groceries they don't buy"],[gMins(w.mLo)+" to "+gMins(w.mHi),"of shopping, packing and cleanup they get back"],["$"+Math.round(w.vLo)+" to $"+Math.round(w.vHi),"that time is worth at the Santa Rosa minimum wage"],["14","meals and snacks they don't plan, buy, cook or pack"]].map(([v,l])=>`<div class="gstat"><b>${esc(v)}</b><span>${esc(l)}</span></div>`).join("")}</div>
    <div class="lbl" style="margin-top:12px">${esc(periodName(q))}</div>
    <div class="gstats">${[[hr(days),"school days with lunch and snacks"],[kids?hr(meals):"Add enrollment",kids?"meals and snacks offered to "+kids+" children":"in Grant details below"],[r(lo)+" to "+r(hi),"in groceries for each child"],[hr(hLo)+" to "+hr(hHi)+" hours","of shopping, packing and cleanup for each family"]].map(([v,l])=>`<div class="gstat"><b>${esc(v)}</b><span>${esc(l)}</span></div>`).join("")}</div>
    ${kids?`<div class="cnt" style="margin-top:8px">Across ${kids} children, that is about ${r(lo*kids)} to ${r(hi*kids)} in groceries families did not have to buy, and ${hr(hLo*kids)} to ${hr(hHi*kids)} hours they did not spend, worth ${r(hLo*kids*G_SAVE.wage)} to ${r(hHi*kids*G_SAVE.wage)} at the Santa Rosa minimum wage.</div>`:""}
    <div class="cnt" style="margin-top:6px">For comparison, the federal child care food program pays centers ${r(fed)} per child for the same lunches and snacks over these days, a basic prepared meal with no allowance for organic food or baking from scratch. It describes the same meals another way, so it is never added to the grocery estimate.</div>
    <div class="cnt" style="margin-top:6px">Every bread, dough and crust is made by hand, with organic and local food, a quality many families would find hard to match at home. Nationally, 19.5 percent of children lived in food insecure households in 2024, and 63 percent of lower income adults in Sonoma County were food insecure.</div>
    <div class="hint">An estimate with its method shown. Groceries use USDA's food plans for ages 2 to 5, thrifty to liberal, with lunch and two snacks taken as 40 to 50 percent of a day's food, and 25 percent added at the high end for organic and local food. Time is 10 to 25 minutes a school day. School days come from the monthly menus, and enrollment from Grant details or the children in TREE. Children who attend part time or are absent save less.</div>
    <div class="cnt">Sources, <a href="https://www.fns.usda.gov/research/cnpp/usda-food-plans/cost-food-monthly-reports" target="_blank" rel="noopener">USDA food plans</a>, <a href="https://www.fns.usda.gov/cacfp/fr-072726" target="_blank" rel="noopener">CACFP rates 2026 to 2027</a>, <a href="https://www.ers.usda.gov/amber-waves/2016/may/investigating-retail-price-premiums-for-organic-foods" target="_blank" rel="noopener">USDA organic price premiums</a>, <a href="https://www.bls.gov/tus/tables/a1-2025.pdf" target="_blank" rel="noopener">American Time Use Survey</a>, <a href="https://www.feedingamerica.org/sites/default/files/2026-08/Map%20the%20Meal%20Gap%202026%20Report.pdf" target="_blank" rel="noopener">Feeding America 2026</a>, <a href="https://www.nbcbayarea.com/news/local/food-insecurity-bay-area/4047203/" target="_blank" rel="noopener">California Health Interview Survey, reported 2026</a>.</div></div></details>`}
// the share of food spending at large retailers, quarter by quarter
function gRetailTrend(from,to){const rows=[];const qs=[...new Set(gLinesAll(from,to).map(x=>quarterOf(x.day)))].sort();
  for(const x of qs){const r=quarterRange(x),L=gLinesAll(r.from,r.to),t=L.reduce((a,y)=>a+(Number(y.total)||0),0),rt=L.filter(y=>y.kind==="retail").reduce((a,y)=>a+(Number(y.total)||0),0);rows.push([quarterName(x),rt,t])}
  return `<div class="lbl" style="margin-top:10px">Share at large retailers, by quarter</div><div class="tlist">${rows.map(([n,rt,t])=>`<div class="prow"><div>${esc(n)}</div><div class="cnt" style="flex:none">${gMoney(rt)} of ${gMoney(t)} · ${gPct(rt,t)}</div></div>`).join("")}</div>`}
// what a producer's marks rest on, folded on the page so a list of farms stays short
