function gWorksheetCsv(){const S=gSet();const lines=gLines(S.start||"0000",S.end||"9999");
  const head=["Date","Invoice","Distributor","Producer","Producer town","Item","Unit","Quantity","Unit price","Total","Budget line","California grown","Organic","Small to midsize","BIPOC, female, veteran or limited resource","Climate smart","To check","Sources"];const uns=new Set(gUnsure().map(u=>u.o.id+"|"+u.i));const chk=(x,p)=>[x.review?"Order read from an email, not yet checked":"",uns.has(x.src+"|"+x.i)?"Meals or education to check":"",p.check||""].filter(Boolean).join(". ");
  const yn=v=>v?"Yes":"";
  const rows=lines.map(x=>{const p=gProducer(x.producer);return [x.day,x.order||"",x.distributor,x.producer,p.town||"",x.item,x.unit||"",x.qty,x.price,x.total,x.use==="education"?"1b Student education":"1a Meals and snacks","Yes",yn(gOrganic(x)),yn(p.smallmid),yn(p.sdlr),yn(p.climate),chk(x,p),(p.sources||[]).join(" ")]});
  // the farms behind each bin, beneath its line
  const out=[head];for(const r of rows)out.push(r);
  const bf=gBinFarms(S.start||"0000",S.end||"9999");if(bf.length){out.push([]);out.push(["Farms behind the FEED bins"]);out.push(["Farm","Town","Weeks","Items","Organic","Small to midsize","BIPOC, female, veteran or limited resource","Climate smart","To check","Sources"]);bf.forEach(f=>{const p=gProducer(f.name);out.push([f.name,f.town||"",f.weeks.size,[...f.items].join("; "),yn(p.organic),yn(p.smallmid),yn(p.sdlr),yn(p.climate),p.check||"",(p.sources||[]).join(" ")])})}
  return out.map(r=>r.map(v=>{const s=String(v??"");return /[",\n]/.test(s)?'"'+s.replace(/"/g,'""')+'"':s}).join(",")).join("\r\n")}

// a summary of the quarter, year or whole grant, laid out to be read, key figures first, then each section as a table
async function gDraft(q){if(!sample){toast("Drafting is not available here. Open TREE and sign in.");return}
  gBusy=true;renderGrant();const {from,to}=quarterRange(q);const lines=gLines(from,to);const sum=a=>a.reduce((t,x)=>t+(Number(x.total)||0),0);
  const prods=[...new Set(lines.map(x=>x.producer))];const ed=gEducation(from,to);const fam=gList("families").filter(x=>x.date>=from&&x.date<=to);
  const words=ed.flatMap(o=>o.obs.slice(0,6).map(n=>`${o.label}. ${firstLine(n.noticed,220)}`)).slice(0,18);
  const prompt=`Draft a quarterly check-in for a California Department of Food and Agriculture Farm to School Incubator grant, for an early childhood program, for ${quarterName(q)}. It has three parts, project progress, successes, and challenges.
Use only what is below. Never add a number, a name or an event that is not here. Where something is missing, leave it out rather than guessing.

The grant's objectives. 1 to 4, buy more California grown, whole or minimally processed food, from small to midsize producers, from BIPOC, female, veteran or limited resource producers, and from producers using climate smart or organic practices. 5 to 7, hands-on food education where children gather, wash and deliver fruit, prepare food with an educator, and work in small groups in the classroom and garden. 8, culturally relevant food education with families.

Food bought this quarter. ${gMoney(sum(lines.filter(x=>x.use!=="education")))} for meals and snacks, ${gMoney(sum(lines.filter(x=>x.use==="education")))} for student education, ${gMoney(sum(lines.filter(gOrganic)))} certified organic, from ${prods.length} producers${prods.length?", "+prods.join(", "):""}.
Farms behind the weekly FEED bins. ${gBinFarms(from,to).map(f=>f.name+(f.town?" in "+f.town:"")).join(", ")||"None recorded"}.
Hands-on food education. ${ed.map(o=>`${o.label}, ${o.obs.length} observations and ${o.plans.length} plans`).join(". ")}.
${words.length?"What educators wrote, in their own words.\n"+words.join("\n"):""}
${fam.length?"Families.\n"+fam.map(x=>x.date+". "+x.text).join("\n"):""}

Write in plain, warm, professional language, in the first person plural, a short paragraph for each part. Do not use colons, em dashes, or analogies.
Return a JSON object with keys "progress", "successes" and "challenges".`;
  try{const out=await sample.json(prompt,{modelTier:"complex",cache:false,purpose:"grant"});const c=s=>String(s||"").replace(/\s*[—–]\s*/g,", ").replace(/:\s*/g,". ").trim();
    await gWrite("q-"+q,{checkin:{progress:c(out?.progress),successes:c(out?.successes),challenges:c(out?.challenges),draftedAt:Date.now()}},{id:"q-"+q,checkin:{}});toast("Drafted. Rewrite it in your own voice.")}
  catch(err){toast(assistError(err||"unknown","Nothing was changed."))}
  gBusy=false;if(view==="grant")renderGrant()}

document.addEventListener("change",async e=>{const t=e.target;if(view!=="grant")return;
  if(t.id==="g-order"){const fs=[...t.files];t.value="";let n=0;
    if(fs.length)toast("Reading");
    for(const f of fs){try{const pdf=/pdf$/i.test(f.type)||/\.pdf$/i.test(f.name);
      const body=pdf?{name:f.name,type:"application/pdf",data:await new Promise(r=>{const rd=new FileReader();rd.onload=()=>r(String(rd.result).split(",")[1]);rd.readAsDataURL(f)})}:{name:f.name,raw:await f.text()};
      const j=await window.FP_API("/api/grant/order",body);if(j&&j.doc){grantRecs.set(j.doc.id,j.doc);n++}}catch(err){toast(`${f.name}. ${(err&&err.message)||"It could not be read."}`)}}
    if(n)toast(`${n} order${n===1?"":"s"} kept`);renderGrant();return}
  if(t.dataset.guse!=null){const use=t.value;
    if(t.dataset.gman){await gWrite("purchases",{list:{[t.dataset.gman]:{use}}})}
    else{const o=grantRecs.get(t.dataset.guse);if(!o)return;const items=(o.items||[]).map((x,i)=>i===+t.dataset.gi?Object.assign({},x,{use,useSet:true}):x);if(db)try{await db.doc("grant/"+o.id).update({items})}catch(err){toast("Could not save that.")}}
    renderGrant();return}
  if(t.dataset.gptown!=null){await gWrite("producers",{list:{[t.dataset.gptown]:{name:t.dataset.gpn,town:t.value.trim()}}},{id:"producers",list:{}});renderGrant();return}
  if(t.dataset.gck){const q=gQ();if(!isQuarter(q))return;await gWrite("q-"+q,{checkin:{[t.dataset.gck]:t.value.trim()}},{id:"q-"+q,checkin:{}});return}
  if(t.dataset.gset){const v=t.type==="number"?Number(t.value)||0:t.value.trim();await gWrite("settings",{[t.dataset.gset]:v},Object.assign({id:"settings"},G_DEFAULT));renderGrant();return}});
document.addEventListener("click",async e=>{const t=e.target.closest("[data-gq],[data-gact],[data-gpf],[data-gfdel],[data-gok],[data-gdel],[data-grevuse],[data-grevkeep],[data-gplace],[data-gfoffer],[data-gfofferno]");if(!t||view!=="grant")return;e.stopImmediatePropagation();const d=t.dataset;
  if(d.gok){if(db)try{await db.doc("grant/"+d.gok).update({review:false,noDate:{__delete__:true},checkedBy:whoAmI(),checkedAt:Date.now()})}catch(err){toast("Could not save that.")}renderGrant();return}
  // the director counts an observation or plan for a food education goal, or sets it aside. Pressing the same choice again clears it.
  // a new reading of an order already checked, used in place of the lines kept, or set aside
  if(d.grevuse){const o=grantRecs.get(d.grevuse),r=o&&o.revision;if(!r||!db)return;
    const patch={items:r.items||[],fulfilled:r.fulfilled||o.fulfilled||"",subtotal:r.subtotal??null,delivery:r.delivery??null,total:r.total??null,distributor:r.distributor||o.distributor||"",noDate:r.noDate?true:{__delete__:true},revision:{__delete__:true},review:!!r.noDate,checkedBy:whoAmI(),checkedAt:Date.now()};
    try{await db.doc("grant/"+o.id).update(patch);toast("The new reading is used.")}catch(err){toast("Could not save that.")}renderGrant();return}
  // the director places a line, meals or education, and it is not asked again
  if(d.gplace){const [id,i]=d.gplace.split("|");const o=grantRecs.get(id);if(!o||!db)return;const items=(o.items||[]).map((x,k)=>k===+i?Object.assign({},x,{use:d.gv,useSet:true}):x);
    try{await db.doc("grant/"+id).update({items});toast(d.gv==="education"?"Counted for student education.":"Counted for meals.")}catch(err){toast("Could not save that.")}renderGrant();return}
  if(d.grevkeep){if(db)try{await db.doc("grant/"+d.grevkeep).update({revision:{__delete__:true}});toast("Kept as it was.")}catch(err){toast("Could not save that.")}renderGrant();return}
  if(d.gdel){if(t.dataset.sure!=="1"){t.dataset.sure="1";t.textContent="Take it out?";return}if(db)try{await db.doc("grant/"+d.gdel).delete();grantRecs.delete(d.gdel)}catch(err){toast("Could not take it out.")}renderGrant();return}
  if(d.gq){gQuarter=d.gq;renderGrant();return}
  if(d.gpf){const cur=gProducer(d.gpn);await gWrite("producers",{list:{[d.gpk]:{name:d.gpn,[d.gpf]:!cur[d.gpf]}}},{id:"producers",list:{}});renderGrant();return}
  if(d.gfdel){await gWrite("families",{list:{[d.gfdel]:{__delete__:true}}});renderGrant();return}
  const a=d.gact;
  if(a==="csv"){const blob=new Blob(["﻿"+gWorksheetCsv()],{type:"text/csv"});const u=URL.createObjectURL(blob);const l=document.createElement("a");l.href=u;l.download=`Farm to School procurement ${iso(new Date())}.csv`;document.body.appendChild(l);l.click();l.remove();setTimeout(()=>URL.revokeObjectURL(u),4000);return}
  if(a==="addbuy"){gAdd={};renderGrant();return}
  if(a==="buycancel"){gAdd=null;renderGrant();return}
  if(a==="buysave"){const v=id=>($("#"+id)?.value||"").trim();const p={id:uid(),date:v("g-bdate"),producer:v("g-bprod"),item:v("g-bitem"),total:Number(v("g-btotal"))||0,use:v("g-buse")||"meals",distributor:"Direct",kind:v("g-bkind")||(G_RETAIL.test(v("g-bprod"))?"retail":""),by:whoAmI(),at:Date.now()};
    if(!p.date||!p.producer||!p.item||!p.total){toast("Add the day, the producer, what it was and the total.");return}
    if(await gWrite("purchases",{list:{[p.id]:p}},{id:"purchases",list:{}})){gAdd=null;toast("Kept")}renderGrant();return}
  if(t.dataset.gfoffer||t.dataset.gfofferno){const x=((gdn&&gdn.offered)||[]).find(y=>y.id===(t.dataset.gfoffer||t.dataset.gfofferno));if(!x)return;
    if(t.dataset.gfoffer){const id=uid();if(!(await gWrite("families",{list:{[id]:{id,date:x.date,text:x.text,by:whoAmI(),from:"garden"}}},{id:"families",list:{}})))return}
    await gdnCall("offer/done",{id:x.id},t.dataset.gfoffer?"Added to the family log.":"Set aside.");renderGrant();return}
  if(a==="fam"){const date=$("#g-fdate")?.value||"",text=($("#g-ftext")?.value||"").trim();if(!date||!text){toast("Add the day and what happened.");return}
    const id=uid();if(await gWrite("families",{list:{[id]:{id,date,text,by:whoAmI()}}},{id:"families",list:{}}))toast("Kept");renderGrant();return}
  if(a==="draft"){if(isQuarter(gQ()))gDraft(gQ());return}},true);


